class UnifiedDataLayer:
    def __init__(self):
        self.identity_map = {}
        self.stats = {"flushes": 0, "rollbacks": 0, "closed_cleanly": 0}

    def run_request_lifecycle(self, should_fail=False):
        # 1. Open session (scoped)
        session_map = {}
        try:
            # 2. Mutate entity
            session_map["order_101"] = {"id": 101, "status": "processing"}
            if should_fail:
                raise ValueError("Business rule violation: Insufficient inventory")
            # 3. Commit & Flush
            self.identity_map.update(session_map)
            self.stats["flushes"] += 1
        except Exception:
            # 4. Rollback
            self.stats["rollbacks"] += 1
        finally:
            # 5. Clean teardown
            session_map.clear()
            self.stats["closed_cleanly"] += 1

udl = UnifiedDataLayer()
udl.run_request_lifecycle(should_fail=False)
udl.run_request_lifecycle(should_fail=True)

print("=== ASYNCSESSION LIFECYCLE SYNTHESIS ===")
print(f"Successful Flushes:       {udl.stats['flushes']}")
print(f"Handled Rollbacks:        {udl.stats['rollbacks']}")
print(f"Clean Session Teardowns:  {udl.stats['closed_cleanly']}")
print(f"Persistent Entities:      {len(udl.identity_map)}")
assert udl.identity_map["order_101"]["status"] == "processing"
print(f"Verified Persistent Status: order_101 -> {udl.identity_map['order_101']['status']}")
print("Full Unit of Work and Identity Map lifecycle certified.")
